insert into public.quiz_configs (subject_id,unit_id,quiz_type,question_count,time_limit_minutes,randomize_questions,randomize_options,is_active) select u.subject_id,u.id,'unit_30',30,30,true,true,true from public.units u join public.subjects s on s.id=u.subject_id where s.code in ('CIV2','LAB1','DCO2','CPEN','DDHH_DIP','DIP','DPC1','LAB2','PEN1','CIV3','COFJ','MERC','ADM1','CIV4','PEN2') and not exists (select 1 from public.quiz_configs qc where qc.quiz_type='unit_30' and qc.unit_id=u.id);
insert into public.quiz_configs (subject_id,unit_id,quiz_type,question_count,time_limit_minutes,randomize_questions,randomize_options,is_active) select s.id,null,'subject_100',100,100,true,true,true from public.subjects s where s.code in ('CIV2','LAB1','DCO2','CPEN','DDHH_DIP','DIP','DPC1','LAB2','PEN1','CIV3','COFJ','MERC','ADM1','CIV4','PEN2') and not exists (select 1 from public.quiz_configs qc where qc.quiz_type='subject_100' and qc.subject_id=s.id);
insert into public.quiz_unit_distribution (quiz_config_id,unit_id,question_count) select qc.id,u.id,25 from public.quiz_configs qc join public.units u on u.subject_id=qc.subject_id join public.subjects s on s.id=qc.subject_id where qc.quiz_type='subject_100' and s.code in ('CIV2','LAB1','DCO2','CPEN','DDHH_DIP','DIP','DPC1','LAB2','PEN1','CIV3','COFJ','MERC','ADM1','CIV4','PEN2') and u.unit_number between 1 and 4 and not exists (select 1 from public.quiz_unit_distribution qud where qud.quiz_config_id=qc.id and qud.unit_id=u.id);
insert into tmp_s345_bank (code,unit_number,qnum,topic_slug,question_text,option_a,option_b,option_c,option_d,correct_key,question_type,difficulty,is_verified) values
  ('DIP',4,1,'cooperacion-juridica-internacional','La cooperación jurídica internacional a un proceso consiste en:','La derogación de las normas procesales del Estado receptor.','El sistema normativo que regula la asistencia, colaboración o ayuda que se otorga a un órgano encargado de decidir un litigio.','La ejecución directa de arrestos por la policía de otro país sin previa solicitud.','La adopción unánime de un solo código de procedimiento para todos los países.','B','conceptual','intermediate',true),
  ('DIP',2,2,'normas-directas-e-indirectas-comunitarias-y-de-lex-police','¿De dónde proviene la obligatoriedad primaria en el denominado “Derecho Comunitario Originario”?','De los tratados fundacionales, modificatorios y complementarios.','De los reglamentos dictados por los ministerios nacionales.','De los fallos de tribunales arbitrales privados.','De las costumbres del comercio marítimo internacional.','A','conceptual','intermediate',true),
  ('DIP',2,3,'puntos-de-conexion-y-calificaciones','¿Qué es el “Punto de Conexión” en la estructura de la norma indirecta?','El elemento técnico que indica el ordenamiento jurídico aplicable a la situación.','El domicilio procesal fijado por los abogados.','El fallo definitivo dictado por el juez de la causa.','La prueba aportada por las partes en la etapa del litigio.','A','conceptual','intermediate',true),
  ('DIP',2,4,'normas-directas-e-indirectas-comunitarias-y-de-lex-police','¿En qué consiste el “efecto directo” de la norma comunitaria?','En la necesidad de ratificación parlamentaria previa para cada acto normativo.','En la derogación automática de todas las constituciones nacionales.','En el derecho de los particulares de solicitar a los jueces nacionales la aplicación directa de la norma comunitaria.','En la obligación del juez de consultar al Parlamento antes de dictar sentencia.','C','conceptual','intermediate',true),
  ('DIP',1,5,'definiciones-objeto-y-finalidad-del-derecho-internacional-privado','Según Antonio Sánchez de Bustamante, ¿cómo se define el Derecho Internacional Privado?','Como una rama del derecho público que sanciona los delitos cometidos por extranjeros en territorio nacional.','Como el conjunto de principios que determinan los límites en el espacio de la competencia legislativa de los Estados cuando ha de aplicarse a relaciones jurídicas sometidas a más de una legislación.','Como el conjunto de principios procesales que regulan exclusivamente los litigios comerciales entre Estados.','Como el código uniforme supranacional aplicable por un tribunal único de la comunidad internacional.','B','conceptual','intermediate',true),
  ('DIP',1,6,'desarrollo-historico-y-fuentes-del-derecho-internacional-privado','¿Quién es considerado la figura más relevante de la Escuela Estatutaria Italiana por sistematizar la aplicación de los estatutos personales, reales y formales?','Acursio.','Azón.','Balduini.','Bartolo de Sassoferrato.','D','conceptual','intermediate',true),
  ('DIP',4,7,'derecho-de-familia','¿Cuáles son los tres criterios atributivos principales para determinar la ley aplicable a la filiación?','La lex loci delicti, la autonomía de la voluntad y el fuero de atracción.','La lex loci solutionis, la ley comercial y el forum shopping.','El personal (nacionalidad/domicilio), la celebración del matrimonio y la lex fori.','El arancelario, la lex rei sitae y la ley del consulado.','C','normative','intermediate',true),
  ('DIP',4,8,'extradicion','En un procedimiento de extradición, el Estado es “requerido” cuando se trata de una extradición:','Simplificada.','De tránsito.','Activa.','Pasiva.','D','conceptual','intermediate',true),
  ('DIP',2,9,'puntos-de-conexion-y-calificaciones','¿Qué caracteriza a los puntos de conexión múltiples “acumulativos”?','Que conceden plazo acumulado para contestar la demanda.','Que la validez o efecto del acto exige la concordancia o aplicación de dos o más leyes.','Que permiten sumar las indemnizaciones fijadas por dos países.','Que exigen la firma de dos o más cónsules.','B','conceptual','intermediate',true),
  ('DIP',4,10,'derecho-de-familia','¿Cuál de los siguientes impedimentos matrimoniales presenta coincidencia general en las distintas legislaciones?','La diferencia de nacionalidad entre los contrayentes.','La falta de edad, ligamen, parentesco en grado prohibido y demencia.','Impedimentos raciales y religiosos.','Impedimentos por discrepancias políticas o ideológicas.','B','conceptual','intermediate',true),
  ('DIP',2,11,'jerarquia-normativa','Según el compendio, ¿cuál es el rasgo distintivo de las leyes del orden internacional respecto a su validez?','Son particulares, temporales y actúan en su órbita sin subordinación jerárquica.','Tienen jerarquía superior a las constituciones nacionales.','Tienen vigencia indefinida e inmutable en todo el planeta.','Son dictadas de forma exclusiva por la Asamblea General de la ONU.','A','conceptual','intermediate',true),
  ('DIP',3,12,'cuestion-previa-o-incidental','Según la teoría de la “Lex Causae” (sostenida por Melchior y Wengler), la cuestión previa debe resolverse aplicando:','El mismo ordenamiento jurídico que regula la acción principal.','El derecho interno del Estado de la nacionalidad del demandante.','Las normas de conflicto de la lex fori.','La costumbre mercantil internacional unificada.','A','conceptual','intermediate',true),
  ('DIP',3,13,'orden-publico-internacional','El orden público internacional opera ante la ley extranjera como un remedio de carácter:','Sancionatorio e imprescriptible.','Exclusivo de materias mercantiles.','De aplicación general y obligatoria a todo caso internacional.','Excepcional.','D','normative','intermediate',true),
  ('DIP',1,14,'desarrollo-historico-y-fuentes-del-derecho-internacional-privado','¿Qué jurista recopiló la labor de los glosadores dando origen a la “Glosa Ordinaria”?','Bartolo de Sassoferrato.','Jacobo de Ravena.','Acursio.','Dumoulin.','C','conceptual','intermediate',true),
  ('DIP',4,15,'relaciones-mercantiles','¿En qué consiste la “autonomía de la voluntad” como factor de conexión en las obligaciones contractuales?','La exención total del pago de impuestos internacionales.','El derecho de rescindir unilateralmente el contrato sin penalización.','La atribución del juez de modificar el objeto contractual por equidad.','La facultad de las partes de elegir expresamente el derecho que regirá su contrato.','D','conceptual','intermediate',true),
  ('DIP',3,16,'orden-publico-internacional','¿Cuáles son las dos excepciones que limitan la aplicación y reconocimiento de la Teoría de los Derechos Adquiridos?','La reciprocidad comercial y la nacionalidad del juez.','La falta de jurisdicción y la caducidad.','El Orden Público y la Institución Desconocida.','El fuero del domicilio y la prueba procesal.','C','conceptual','intermediate',true),
  ('DIP',3,17,'jurisdiccion-internacional','El principio tradicional “actor sequitur forum rei” determina la competencia judicial basada principalmente en:','El domicilio del demandado.','La nacionalidad del demandante.','El lugar de cumplimiento del contrato.','La ubicación de los bienes muebles del causante.','A','conceptual','intermediate',true),
  ('DIP',2,18,'normas-directas-e-indirectas-comunitarias-y-de-lex-police','¿En qué se diferencia sustancialmente la regla de conflicto de la norma de policía en cuanto a la consideración del derecho extranjero?','La de conflicto es punitiva y la de policía es mercantil.','La de conflicto la dictan los jueces y la de policía el poder ejecutivo.','No existe diferencia, ambas aplican obligatoriamente derecho extranjero.','La de conflicto admite aplicar derecho extranjero; la de policía remite e impone de forma exclusiva el derecho propio.','D','conceptual','intermediate',true),
  ('DIP',3,19,'cuestion-previa-o-incidental','Para que se configure una verdadera cuestión previa de DIP, se requiere que la norma de conflicto del foro someta la cuestión principal a:','Un tribunal arbitral internacional de comercio.','La ley del lugar de ejecución del fallo.','Un derecho extranjero que contenga una norma de conflicto distinta para la cuestión previa.','El derecho sustantivo interno de la lex fori.','C','conceptual','intermediate',true),
  ('DIP',2,20,'normas-directas-e-indirectas-comunitarias-y-de-lex-police','¿Qué tratado internacional se cita como ejemplo de aplicación de normas materiales directas?','La Convención de las Naciones Unidas sobre los Contratos de Compraventa Internacional de Mercaderías.','El Convenio de La Haya sobre Adopción Internacional.','La Convención de Viena sobre el Derecho de los Tratados.','El Pacto de San José de Costa Rica.','A','conceptual','intermediate',true),
  ('DIP',3,21,'jurisdiccion-internacional','Si un Estado dicta una sentencia aplicando un criterio de competencia exorbitante que invada la competencia atribuida a Ecuador, la sentencia:','Se homologará de forma condicional.','Tendrá valor jurídico pleno en Ecuador.','Producirá cosa juzgada únicamente en materia penal.','Carecerá de efectos jurídicos para los tribunales ecuatorianos.','D','conceptual','intermediate',true),
  ('DIP',1,22,'desarrollo-historico-y-fuentes-del-derecho-internacional-privado','Según la posición positivista, ¿cómo se conciben los Principios Generales del Derecho?','Como criterios rectores esenciales que se obtienen por abstracción y generalización de las normas vigentes.','Como simples opiniones académicas sin valor jurídico.','Como normas religiosas divinas inmutables preexistentes.','Como dogmas absolutos e independientes de la labor legislativa del Estado.','A','conceptual','intermediate',true),
  ('DIP',4,23,'relaciones-mercantiles','¿Por qué la doctrina moderna prefiere hablar de Derecho Mercantil Internacional en lugar de Derecho Comercial Internacional?','Porque el comercio internacional está prohibido por los tratados regionales.','Porque el concepto de comercio se limita al trueque entre Estados.','Porque las relaciones económicas modernas superan el estricto concepto de comercio abarcando actos en masa, empresas y el mercado.','Porque se aplica únicamente a los actos de intermediación bancaria.','C','conceptual','intermediate',true),
  ('DIP',1,24,'desarrollo-historico-y-fuentes-del-derecho-internacional-privado','¿En qué siglo se ubica el surgimiento y desarrollo de la labor de los Postglosadores, Comentaristas o Conciliadores?','Siglo XIV.','Siglo XI.','Siglo XVI.','Siglo XII.','A','conceptual','intermediate',true),
  ('DIP',4,25,'existencia-estado-y-capacidad-de-las-personas-fisicas','En caso de desaparición de registros o documentos por situaciones excepcionales como guerras, las legislaciones suelen:','Exigir la celebración de un nuevo matrimonio bajo la lex fori.','Declarar la inexistencia automática de todos los matrimonios afectados.','Flexibilizar las exigencias procesales y aceptar prueba supletoria.','Derogar los tratados internacionales sobre estado civil.','C','conceptual','intermediate',true),
  ('DIP',3,26,'fraude-a-la-ley','En el emblemático “Caso Bauffremont”, ¿qué conducta configuró el fraude a la ley según el Tribunal de Casación francés?','La venta no autorizada de inmuebles situados en Rumania.','El no pago de las pensiones alimenticias en territorio francés.','La naturalización fraudulenta en Alemania para divorciarse y eludir la ley imperativa francesa que prohibía el divorcio.','La falsificación del acta de matrimonio celebrada en Francia.','C','normative','intermediate',true),
  ('DIP',3,27,'fraude-a-la-ley','De acuerdo con la Convención Interamericana sobre Normas Generales de DIP, determinar la intención fraudulenta de las partes corresponde a:','Una comisión técnica de peritos procesales.','La aprobación por parte del cónsul del Estado de origen.','El juicio de las autoridades competentes del Estado receptor.','La Corte Internacional de Justicia de forma exclusiva.','C','conceptual','intermediate',true),
  ('DIP',4,28,'existencia-estado-y-capacidad-de-las-personas-fisicas','La capacidad jurídica de las personas físicas en el DIP se conceptualiza como:','La posición estática dentro del grupo familiar.','La calidad otorgada exclusivamente por el lugar de celebración del acto.','El mero hecho biológico de la concepción.','El conjunto de condiciones puesto en acción para adquirir derechos y contraer obligaciones.','D','conceptual','intermediate',true),
  ('DIP',2,29,'puntos-de-conexion-y-calificaciones','¿Cuáles son los puntos de conexión “relativos a los actos”?','Los que determinan la capacidad civil de ejercicio.','Los que regulan el nombramiento de apoderados.','Los que hacen referencia a hechos y actos jurídicos.','Los que sancionan las faltas éticas procesales.','C','conceptual','intermediate',true),
  ('DIP',1,30,'desarrollo-historico-y-fuentes-del-derecho-internacional-privado','La Organización Mundial del Comercio (OMC) fue creada mediante el Acuerdo de Marrakech en 1994 como resultado de:','El Convenio de Berna de 1886.','La Ronda Uruguay auspiciada por el GATT.','La Conferencia de Bretton Woods de 1944.','La Carta del Atlántico firmada en 1957.','B','conceptual','intermediate',true),
  ('DPC1',2,1,'principios-y-metodos-de-interpretacion-constitucional-en-la-legislacion-ecuatoriana','Para que una medida respete el principio de proporcionalidad, es necesario, entre otros elementos, que:','Sea aprobada por mayoría simple en la Asamblea.','Solo cumpla con ser conveniente políticamente.','Sea recomendada por organismos internacionales.','Proteja un fin constitucionalmente válido, sea idónea, necesaria y exista equilibrio entre protección y restricción.','D','conceptual','intermediate',true),
  ('DPC1',1,2,'doctrina-y-principios-procesales','El principio de impulso de oficio establece que:','El impulso corresponde únicamente al órgano administrativo.','El proceso avanza solo a petición de la parte demandada.','Las partes son las únicas responsables de impulsar el proceso.','La jueza o juez debe impulsar de oficio los procesos hasta su conclusión, salvo excepciones previstas.','D','conceptual','intermediate',true),
  ('DPC1',2,3,'principios-y-metodos-de-interpretacion-constitucional-en-la-legislacion-ecuatoriana','Cuando un órgano de justicia constitucional fija parámetros interpretativos de la Constitución, estos se caracterizan por:','Tener fuerza vinculante como precedente.','Ser recomendaciones sin efectos prácticos.','Ser revisables únicamente por jueces penales.','Ser aplicables solo en la misma causa.','A','normative','intermediate',true),
  ('DPC1',2,4,'principios-y-metodos-de-interpretacion-constitucional-en-la-legislacion-ecuatoriana','¿Qué criterio debe seguirse cuando existen varias normas o interpretaciones aplicables a un mismo caso?','Escoger la que tenga menos requisitos formales.','Escoger la más antigua.','Escoger la que más proteja los derechos de la persona.','Escoger la más favorable al Estado.','C','conceptual','intermediate',true),
  ('DPC1',1,5,'derecho-procesal-constitucional','¿Cuál es la finalidad principal de la justicia constitucional?','Garantizar jurisdiccionalmente los derechos y asegurar la supremacía de la Constitución.','Organizar el sistema electoral.','Regular la estructura administrativa del Estado.','Regular las políticas económicas del gobierno.','A','conceptual','intermediate',true),
  ('DPC1',3,6,'accion-por-incumplimiento-y-acciones-extraordinarias','La acción de repetición tiene por objeto declarar y hacer efectiva la responsabilidad patrimonial por dolo o culpa grave de las servidoras y servidores públicos, y prescribirá en el plazo de:','Dos años, contados desde la notificación de la resolución.','Cinco años, contados desde la violación del derecho.','Tres años, contados a partir de la realización del pago hecho por el Estado.','Un año, contado desde la sentencia condenatoria.','C','conceptual','intermediate',true),
  ('DPC1',3,7,'medidas-cautelares-y-acciones-de-proteccion-de-derechos','Según el artículo 87 de la Constitución, las medidas cautelares pueden ser interpuestas de manera conjunta o independientemente de las acciones constitucionales de protección de derechos, con el objeto de:','Reparar integralmente el daño material ocasionado al afectado.','Evitar o hacer cesar la violación o amenaza de violación de un derecho.','Sancionar a la autoridad responsable de la violación del derecho.','Declarar la responsabilidad patrimonial del servidor público infractor.','B','normative','intermediate',true),
  ('DPC1',3,8,'medidas-cautelares-y-acciones-de-proteccion-de-derechos','La acción de hábeas data tiene por objeto garantizar judicialmente a toda persona:','La eliminación de cualquier dato personal que conste en archivos públicos.','El acceso a los documentos, datos genéticos, bancos o archivos de datos personales e informes que sobre sí misma, o sobre sus bienes, estén en poder de entidades públicas o privadas.','La reparación económica por el uso indebido de su información personal.','La sanción de quienes difundan datos personales sin autorización.','B','conceptual','intermediate',true),
  ('DPC1',3,9,'medidas-cautelares-y-acciones-de-proteccion-de-derechos','En el trámite de hábeas corpus, la persona procesada tiene derecho a la inmediata excarcelación cuando haya caducado la prisión preventiva por haber transcurrido:','Tres meses en todos los delitos sin distinción.','Cuatro meses en delitos con prisión y ocho meses en delitos con reclusión.','Seis meses en delitos sancionados con prisión y un año en delitos sancionados con reclusión.','Un año en delitos con prisión y dos años en delitos con reclusión.','C','conceptual','intermediate',true),
  ('DPC1',3,10,'medidas-cautelares-y-acciones-de-proteccion-de-derechos','Cuando la orden de privación de la libertad haya sido dispuesta en un proceso penal, el recurso de hábeas corpus se interpondrá ante:','La Defensoría del Pueblo.','La Corte Constitucional.','Cualquier jueza o juez del domicilio del accionante.','La Corte Provincial de Justicia.','D','conceptual','intermediate',true),
  ('DPC1',3,11,'medidas-cautelares-y-acciones-de-proteccion-de-derechos','Uno de los requisitos para presentar la acción de protección es:','La presentación de pruebas documentales que acrediten el daño.','La existencia de un proceso penal previo en curso.','Inexistencia de otro mecanismo de defensa judicial adecuado y eficaz para proteger el derecho violado.','El agotamiento previo de la vía administrativa ordinaria.','C','conceptual','intermediate',true),
  ('DPC1',3,12,'accion-por-incumplimiento-y-acciones-extraordinarias','En la acción por incumplimiento, si la autoridad pública o persona particular no contestare el reclamo previo, se considerará configurado el incumplimiento en el término de:','Sesenta días.','Treinta días.','Cuarenta días.','Veinte días.','C','conceptual','intermediate',true),
  ('DPC1',2,13,'principios-y-metodos-de-interpretacion-constitucional-en-la-legislacion-ecuatoriana','El principio de proporcionalidad se utiliza cuando:','El juez quiere reducir la duración del proceso.','Las reglas de solución de antinomias no resuelven la contradicción entre principios o normas.','Se trata de normas meramente reglamentarias.','No existe conflicto entre normas o principios.','B','conceptual','intermediate',true),
  ('DPC1',2,14,'principios-y-metodos-de-interpretacion-constitucional-en-la-legislacion-ecuatoriana','La ponderación supone:','Priorizar siempre los derechos colectivos sobre los individuales.','Establecer una preferencia entre principios y normas según las circunstancias del caso y el grado de afectación.','Dejar de lado los derechos para favorecer la eficacia administrativa.','Elegir automáticamente la norma jerárquicamente superior.','B','conceptual','intermediate',true),
  ('DPC1',2,15,'disposiciones-comunes-de-las-garantias-jurisdiccionales','La llamada formalidad condicionada implica que:','Las formalidades pueden adecuarse al logro de los fines del proceso, sin sacrificar la justicia por meras omisiones formales.','Toda omisión formal anula automáticamente el proceso.','No se exige ningún tipo de formalidad.','Las formas procesales son rígidas e inmodificables.','A','conceptual','intermediate',true),
  ('DPC1',2,16,'disposiciones-comunes-de-las-garantias-jurisdiccionales','Según el principio de comprensión efectiva, ¿cómo deberá la jueza o juez redactar sus sentencias?','De forma clara, concreta, inteligible, asequible y sintética.','De forma técnica, extensa y doctrinaria.','De forma que se reúna la mayor cantidad de cuestiones debatidas.','De forma oral exclusivamente, sin necesidad de constancia escrita.','A','conceptual','intermediate',true),
  ('DPC1',2,17,'disposiciones-comunes-de-las-garantias-jurisdiccionales','Según el Art. 86 de la Constitución, el procedimiento de las garantías jurisdiccionales será:','Hábil únicamente en días y horas laborables.','Sencillo, rápido y eficaz, y oral en todas sus fases e instancias.','Escrito en todas sus fases e instancias.','Aplicable solo con patrocinio de un abogado.','B','normative','intermediate',true),
  ('DPC1',3,18,'medidas-cautelares-y-acciones-de-proteccion-de-derechos','¿Qué garantía protege derechos específicos como el derecho de libertad, integridad física y vida?','La acción de cumplimiento.','La acción de protección.','El hábeas corpus.','El hábeas data.','C','conceptual','intermediate',true),
  ('DPC1',2,19,'disposiciones-comunes-de-las-garantias-jurisdiccionales','Según el Art. 86 de la Constitución, ¿qué ocurre si la entidad pública requerida no demuestra lo contrario o no suministra información?','Se presumirán ciertos los fundamentos alegados por la persona accionante.','Se archivará inmediatamente la causa.','Se inadmitirá la acción en la primera providencia.','Se suspenderá la audiencia hasta nueva fecha.','A','normative','intermediate',true),
  ('DPC1',2,20,'disposiciones-comunes-de-las-garantias-jurisdiccionales','Según la LOGJCC, ¿quién será competente para conocer las garantías jurisdiccionales?','La Corte Constitucional en única instancia.','La Corte Provincial del domicilio del accionante.','Cualquier jueza o juez de primera instancia del lugar donde se origina el acto u omisión o donde se producen sus efectos.','El juez de turno exclusivamente en días feriados.','C','conceptual','intermediate',true),
  ('DPC1',2,21,'disposiciones-comunes-de-las-garantias-jurisdiccionales','¿En qué artículo de la Constitución de la República se establece el derecho al debido proceso?','Artículo 84.','Artículo 76.','Artículo 86.','Artículo 85.','B','normative','intermediate',true),
  ('DPC1',2,22,'disposiciones-comunes-de-las-garantias-jurisdiccionales','¿De qué maneras puede terminar el procedimiento constitucional?','Mediante resolución de la Corte Constitucional.','Mediante auto definitivo que declare el desistimiento o apruebe el allanamiento, o mediante sentencia.','Únicamente mediante sentencia.','Únicamente mediante allanamiento de la parte accionada.','B','conceptual','intermediate',true),
  ('DPC1',2,23,'disposiciones-comunes-de-las-garantias-jurisdiccionales','Cuando la jueza o juez ordene la práctica de pruebas en audiencia, ¿cuál es el término en el cual se practicarán?','No será mayor de cuarenta y ocho horas.','No será mayor de ocho días y por una sola vez.','No será mayor de veinticuatro horas.','No será mayor de tres días y por una sola vez.','B','conceptual','intermediate',true),
  ('DPC1',4,24,'control-abstracto-de-constitucionalidad','Las sentencias que se dicten en ejercicio del control abstracto de constitucionalidad surten efectos de cosa juzgada y producen efectos generales:','Solo entre las partes.','Hacia el futuro.','Hacia el pasado.','Únicamente para casos análogos.','B','conceptual','intermediate',true),
  ('DPC1',4,25,'control-concreto-de-constitucionalidad','De acuerdo con el criterio de clasificación, si el control se efectúa respecto de normas relevantes para la decisión de un juicio en particular se llama:','Ex ante.','Concreto.','Abstracto.','Represivo.','B','conceptual','intermediate',true),
  ('DPC1',4,26,'control-abstracto-de-constitucionalidad','La demanda de inconstitucionalidad puede ser propuesta por:','Exclusivamente la máxima autoridad de la entidad afectada.','Únicamente el Defensor del Pueblo.','Solo los asambleístas en ejercicio.','Cualquier persona, individual o colectivamente.','D','conceptual','intermediate',true),
  ('DPC1',4,27,'control-abstracto-de-constitucionalidad','Según el sustento teórico, son válidas las normas que:','Son conformes a las metanormas en las que se fundamentan.','Emanan de la Asamblea Nacional.','Han sido publicadas en el Registro Oficial.','No han sido derogadas por una norma posterior.','A','conceptual','intermediate',true),
  ('DPC1',4,28,'control-concreto-de-constitucionalidad','El control concreto tiene como finalidad:','Garantizar la constitucionalidad de la aplicación de las disposiciones jurídicas dentro de los procesos judiciales.','Garantizar la unidad y coherencia del ordenamiento jurídico.','Eliminar las incompatibilidades normativas de carácter general.','Controlar las enmiendas y reformas constitucionales.','A','conceptual','intermediate',true),
  ('DPC1',3,29,'medidas-cautelares-y-acciones-de-proteccion-de-derechos','Compete a las juezas y los jueces de primer nivel conocer y resolver, en primera instancia:','La acción extraordinaria de protección contra decisiones de la justicia indígena.','Las acciones de inconstitucionalidad de leyes y actos normativos.','La acción de protección, hábeas corpus, hábeas data, acceso a la información pública, petición de medidas cautelares y ejercer control concreto.','El control abstracto de los tratados internacionales.','C','conceptual','intermediate',true),
  ('DPC1',4,30,'control-abstracto-de-constitucionalidad','Para el control constitucional de los tratados internacionales, la Corte Constitucional efectuará un control:','Formal y rogado.','Abstracto y automático.','Material y represivo.','Concreto y posterior.','B','conceptual','intermediate',true),
  ('LAB2',1,1,'procedimientos-judiciales-en-materia-laboral','Un restaurante es demandado por un ex-mesero que exige el pago de fondos de reserva. El propietario del restaurante, al contestar la demanda, demuestra que el mesero hurtó dinero de la caja registradora el último día de trabajo y desea aprovechar el mismo juicio para exigirle judicialmente la devolución del dinero. ¿Qué figura de la contestación expresa debe activar?','Negativa presunta de los hechos del actor.','Rebeldía propia con amparo de derecho.','Contradecir los hechos y el derecho y, además, reconvenir (presentar una contrademanda).','Allanamiento parcial con reserva de ley.','C','case_based','intermediate',true),
  ('LAB2',4,2,'jubilacion','Lucía cesó en sus funciones laborales hace 3 años. Durante su trayectoria profesional registró 110 imposiciones mensuales. Recientemente ha sido diagnosticada con una incapacidad absoluta y permanente para todo trabajo y acude al IESS a tramitar su pensión por invalidez. ¿Por qué razón legal el IESS debe denegar la solicitud de jubilación por invalidez de Lucía según el Art. 186?','Exclusivamente porque su cese ocurrió hace más de 2 años, sin importar el número de aportes.','Porque la incapacidad sobrevenida en período de inactividad no está cubierta por la Ley de Seguridad Social.','Porque incumple tanto el plazo límite posterior al cese (supera los 2 años) como el mínimo de aportaciones exigido para cesantes (no alcanza 120 imposiciones).','Exclusivamente porque no alcanza las 360 imposiciones exigidas para la jubilación ordinaria.','C','case_based','intermediate',true),
  ('LAB2',4,3,'huelga','Instaurado el conflicto colectivo, la autoridad laboral convoca a las partes a las audiencias de la etapa de conciliación obligatoria. El empleador no asiste a la primera reunión invocando motivos personales, y a la segunda convocatoria vuelve a faltar sin justificar causa alguna. Según el catálogo de procedencia del Art. 497 del Código del Trabajo, ¿qué derecho les asiste a los trabajadores en este escenario?','Debe reiniciarse de cero el proceso con una nueva notificación mediante la fuerza pública.','Procede la declaratoria de huelga por haber faltado el empleador sin causa a dos reuniones consecutivas en la etapa de conciliación obligatoria.','Se declara automáticamente archivado el pliego de peticiones por falta de interés procesal del empleador.','El Ministerio del Trabajo debe multar al empleador con diez salarios básicos antes de permitir cualquier medida.','B','case_based','intermediate',true),
  ('LAB2',1,4,'procedimientos-judiciales-en-materia-laboral','Un ex-obrero de una constructora presenta una demanda laboral. Al momento de señalar contra quién dirige la acción, el trabajador no recuerda el nombre del representante legal inscrito en la Superintendencia de Compañías, por lo que decide demandar directamente al Ingeniero de Obra, quien era la persona que le impartía órdenes y controlaba su asistencia diariamente. De acuerdo con el Art. 33 del COGEP, ¿es válida esta designación?','Es válida a medias: el juez aceptará la demanda pero obligará al trabajador a pagar los costos de la investigación del verdadero representante en un término de 3 días.','Es inválida y produce la inadmisión inmediata de la demanda por falta de legitimidad pasiva en la causa.','No es válida, porque en las acciones contra personas jurídicas es obligatorio citar únicamente al representante legal que conste en el nombramiento inscrito en el Registro Mercantil.','Es válida, puesto que en materia laboral las acciones pueden dirigirse contra cualquier persona que a nombre de sus principales ejerza funciones de dirección y administración, aun sin tener poder escrito y suficiente.','D','case_based','intermediate',true),
  ('LAB2',4,5,'jubilacion','Jorge cesó en su actividad laboral hace 18 meses (1 año y medio) y desde entonces no ha vuelto a cotizar ni ha percibido subsidios. Durante toda su vida laboral acumuló 135 imposiciones mensuales. Hoy sufre una enfermedad degenerativa que le produce incapacidad absoluta y permanente para todo trabajo. Jorge no recibe ninguna otra pensión de jubilación. De acuerdo con el numeral II del Art. 186, ¿qué determina la ley sobre la solicitud de jubilación por invalidez de Jorge?','Se le niega el derecho por encontrarse cesante al momento de diagnosticarse la incapacidad.','Se le otorga el derecho, pues la incapacidad ocurrió dentro de los 2 años posteriores al cese y acumula más de 120 imposiciones mensuales.','Se le niega el derecho, porque al estar cesante requería haber acumulado un mínimo de 180 imposiciones.','Se le otorga el derecho únicamente si demuestra haber aportado en los 6 meses anteriores a la enfermedad.','B','case_based','intermediate',true),
  ('LAB2',4,6,'jubilacion','Carlos se encuentra trabajando activamente en una empresa y sufre un accidente grave que le genera una incapacidad absoluta y permanente para todo trabajo. Al revisar sus registros en el IESS, cuenta con un total de 75 imposiciones mensuales acumuladas, habiendo aportado de manera ininterrumpida durante los últimos 12 meses previos al siniestro. ¿Tiene Carlos derecho a la pensión de jubilación por invalidez según el numeral I del Art. 186?','No, porque la incapacidad por accidente de trabajo solo da derecho a un subsidio temporal, no a la jubilación por invalidez.','Sí, pero únicamente si demuestra haber permanecido en cesantía durante los últimos 120 días.','Sí, porque supera el mínimo de 60 imposiciones mensuales y cuenta con al menos 6 imposiciones inmediatamente previas a la incapacidad.','No, porque necesita acreditar un mínimo de 120 imposiciones mensuales para cualquier caso de invalidez.','C','case_based','intermediate',true),
  ('LAB2',4,7,'alegato-final','En un juicio por despido intempestivo, la empresa sostiene que el trabajador firmó una renuncia voluntaria. En su alegato de clausura, el abogado del trabajador señala: “La contraparte argumentará que existe un documento firmado de renuncia; sin embargo, con el peritaje caligráfico y la confesión judicial del gerente se demostró que dicha firma fue obtenida bajo presión y amenaza de denuncia penal, destruyendo el consentimiento requerido por ley”. ¿Qué técnica persuasiva de litigación está empleando el abogado en este fragmento?','Formulación de una propuesta de sentencia condicional.','Planteamiento de un lema de clausura en la fase introductoria.','Anticipación a los argumentos más fuertes de la contraparte y refutación directa de su hipótesis probatoria.','Improvisación de la teoría del caso al finalizar el debate.','C','case_based','intermediate',true),
  ('LAB2',4,8,'jubilacion','Carlos se encuentra trabajando activamente en una empresa y sufre un accidente grave que le genera una incapacidad absoluta y permanente para todo trabajo. Al revisar sus registros en el IESS, cuenta con un total de 75 imposiciones mensuales acumuladas, habiendo aportado de manera ininterrumpida durante los últimos 12 meses previos al siniestro. ¿Tiene Carlos derecho a la pensión de jubilación por invalidez según el numeral I del Art. 186?','Sí, porque supera el mínimo de 60 imposiciones mensuales y cuenta con al menos 6 imposiciones inmediatamente previas a la incapacidad.','Sí, pero únicamente si demuestra haber permanecido en cesantía durante los últimos 120 días.','No, porque necesita acreditar un mínimo de 120 imposiciones mensuales para cualquier caso de invalidez.','No, porque la incapacidad por accidente de trabajo solo da derecho a un subsidio temporal, no a la jubilación por invalidez.','A','case_based','intermediate',true),
  ('LAB2',4,9,'contrato-colectivo-de-trabajo','Un trabajador firma un contrato individual de trabajo en el cual pacta un fondo de capacitación inferior al establecido en el Contrato Colectivo de la empresa. Al momento de reclamar la diferencia, la gerencia argumenta que prevalece la autonomía de la voluntad reflejada en el contrato individual que el trabajador firmó voluntariamente. Considerando la jerarquía y fuerza vinculante del Contrato Colectivo de Trabajo, ¿cuál de las siguientes afirmaciones es jurídicamente correcta?','La cláusula del contrato individual es válida únicamente si cuenta con el visto bueno del inspector del trabajo.','El Contrato Colectivo tiene mayor peso jurídico que los contratos individuales de trabajo y debe ser respetado por encima de acuerdos particulares.','El contrato individual prevalece siempre que haya sido firmado libremente por el trabajador.','Ambas partes deben someter la controversia a un arbitraje privado para determinar qué cláusula se aplica.','B','case_based','intermediate',true),
  ('LAB2',2,10,'demanda-laboral','Un trabajador demanda el pago de horas extras afirmando que laboraba de 08:00 a 20:00. El empleador, en su contestación escrita, admite que el trabajador laboró en la empresa, pero niega rotundamente que haya trabajado fuera de su jornada ordinaria de 08:00 a 17:00. Aplicando lo señalado por el maestro Arazi Roland sobre la importancia de la contestación, ¿qué efecto produce esta contestación en el juicio?','Exime al trabajador de probar que trabajó en la empresa, delimitando el tema de la prueba exclusivamente a la existencia y realización de las horas extras.','Cambia el procedimiento sumario a un procedimiento ordinario por mutuo acuerdo de las partes.','Obliga al juez a dar por terminado el juicio porque ya hay un acuerdo parcial sobre la existencia de la relación laboral.','Elimina la validez de la demanda por haberse producido una contradicción sustancial.','A','case_based','intermediate',true),
  ('LAB2',2,11,'la-prueba-en-materia-laboral','En una demanda por despido intempestivo, el actor adjunta como prueba documental unas capturas de pantalla impresas de chats de WhatsApp y un acta de finiquito no firmada. La empresa demandada, al contestar la demanda, guarda absoluto silencio sobre estos documentos y se limita a negar el despido de forma general. ¿Qué consecuencia procesal acarrea este silencio según el COGEP?','El juez desechará automáticamente los documentos por no haber sido objetados por el actor.','El silencio o la falta de pronunciamiento concreto sobre la autenticidad de la prueba documental de la contraparte puede ser apreciada por el juez como una admisión de su autenticidad.','Provoca la nulidad parcial de la contestación por falta de firma del representante legal.','Se suspende la tramitación del proceso sumario hasta que se realice un peritaje informático de oficio.','B','case_based','intermediate',true),
  ('LAB2',4,12,'contrato-colectivo-de-trabajo','El sindicato de la empresa “Manufacturas del Norte S.A.” y los directivos firmaron un acuerdo sobre aumentos salariales y permisos de capacitación. Sin embargo, redactaron el documento de forma privada y no lo suscribieron ante el Director Regional del Trabajo ni lo inscribieron en dicha dependencia. Meses después, la empresa suspende los beneficios argumentando que el contrato carece de validez legal. Con base en los elementos formales señalados por el Código del Trabajo y la doctrina de Jorge Vásquez, ¿es jurídicamente válido dicho contrato colectivo?','Sí, porque la voluntad de las partes manifestada de forma escrita es suficiente para otorgar plena validez al acuerdo.','No, porque para que el contrato colectivo tenga validez y surta efectos requiere formalidades obligatorias como ser otorgado ante la autoridad competente (Director Regional) y ser registrado.','No, salvo que se demuestre que el contrato fue aprobado mediante asamblea general sin la presencia del empleador.','Sí, pero sus efectos se limitan únicamente a los dirigentes sindicales que firmaron el documento.','B','case_based','intermediate',true),
  ('LAB2',4,13,'contrato-colectivo-de-trabajo','En la empresa “Logística del Pacífico S.A.”, un grupo de trabajadores que no pertenece al sindicato mayoritario consulta a la dirección de Recursos Humanos si las mejoras salariales y los beneficios estipulados en el Contrato Colectivo recientemente suscrito les son aplicables. El representante del empleador sostiene que dichos beneficios son exclusivos para los afiliados a la organización sindical. Con base en las características fundamentales del Contrato Colectivo descritas en el texto, ¿es correcta la postura de la empresa?','No, porque una de sus características esenciales es que aplica para todos y cada uno de los trabajadores de la empresa, aunque no estén afiliados al sindicato.','No, pero su aplicación a los no afiliados está sujeta a que estos reduzcan sus horas de jornada laboral.','Sí, porque el contrato colectivo genera derechos únicamente para quienes pagan la cuota sindical de la organización.','Sí, pero únicamente si el Ministerio del Trabajo emite una resolución especial de extensión para los no afiliados.','A','case_based','intermediate',true),
  ('LAB2',1,14,'procedimientos-judiciales-en-materia-laboral','Un trabajador decide demandar a la compañía “Textiles S.A.” por despido intempestivo, pero también incluye de forma individual en la demanda al Gerente Administrador que firmó su memorando de despido. El abogado de la empresa alega que el administrador no debe pagar nada porque solo es un empleado más y no el dueño de las acciones. Según el Art. 36 del Código del Trabajo, ¿cómo opera la responsabilidad en este escenario?','Existe responsabilidad solidaria entre el empleador (persona jurídica) y sus representantes (directores, gerentes o administradores), por lo que el trabajador puede exigir el pago total de las indemnizaciones a cualquiera de los dos.','El administrador solo responde con un porcentaje equivalente a las acciones que posea dentro de la composición de la empresa.','El proceso se vuelve nulo debido a que no se puede demandar a una persona natural y a una persona jurídica dentro de la misma causa laboral.','El administrador queda exento de toda responsabilidad penal y civil, ya que la personería jurídica de la empresa absorbe la totalidad de las deudas.','A','case_based','intermediate',true),
  ('LAB2',3,15,'fondo-de-reserva-desahucio-y-despido-intempestivo','Un nuevo empleado ingresa a una empresa en el año 2024 y no manifiesta su voluntad sobre el manejo de su fondo de reserva. ¿Cómo debe proceder el empleador respecto al pago de este beneficio según la reforma de 2009?','Debe retener el valor en una cuenta interna hasta que el trabajador decida.','Debe esperar a que el trabajador cumpla un año de labores para iniciar el pago.','Debe pagar mensualmente de forma directa al trabajador el 8,33% de su sueldo.','Debe depositar obligatoriamente el valor en el IESS para su acumulación.','C','conceptual','intermediate',true),
  ('LAB2',4,16,'contrato-colectivo-de-trabajo','El contrato colectivo obligatorio para el sector platanero de la provincia de Los Ríos se encuentra en los últimos meses de su prórroga de dos años. Ni las asociaciones de trabajadores ni los empleadores que representan las dos terceras partes acordaron una revisión o renovación del instrumento. ¿Qué efecto jurídico sobreviene al finalizar el plazo ante la falta de un nuevo acuerdo de las mayorías, según el Art. 260 del Código del Trabajo?','El Estado asume la administración de las empresas de dicho sector productivo.','Pone fin a la vigencia del contrato colectivo obligatorio y deja en libertad a empleadores y trabajadores para concertar las nuevas condiciones en cada empresa.','Se imponen las multas previstas en el régimen sancionatorio del Ministerio del Trabajo a todos los empleadores.','El contrato obligatorio se prorroga automáticamente por diez años adicionales de forma indefinida.','B','case_based','intermediate',true),
  ('LAB2',2,17,'excepciones-previas-en-materia-laboral','La defensa técnica de una fábrica textil contestó una demanda laboral planteando únicamente la excepción de “pago total de la obligación”. Cinco días después, el abogado se da cuenta de que también debía plantear la excepción previa de “prescripción del derecho”. ¿Hasta qué momento procesal tiene oportunidad de reformar sus excepciones según el Art. 151 del COGEP?','Hasta antes de que el juzgador dicte la providencia convocando a la audiencia única.','Al momento de interponer el recurso de apelación ante la Corte Provincial.','En cualquier momento del proceso, incluso dentro de la segunda fase de la audiencia única.','Únicamente dentro de las primeras 48 horas posteriores a la presentación de la contestación inicial.','A','case_based','intermediate',true),
  ('LAB2',4,18,'contrato-colectivo-de-trabajo','La directiva de un sindicato de la industria textil busca comprender el alcance territorial e institucional de un Contrato Colectivo Ordinario frente a la posibilidad de impulsar un Contrato Ley para toda la actividad textil ecuatoriana. A partir de la distinción dogmática entre ambos tipos de contratación descrita en la normativa y doctrina laboral, ¿cuál es la diferencia fundamental en cuanto a su ámbito de aplicación?','El contrato ordinario rige a nivel nacional para todas las industrias, mientras que el contrato ley rige solo dentro de una fábrica.','El contrato ordinario es de cumplimiento voluntario, mientras que el contrato ley solo aplica a las empresas del sector público.','El contrato ley solo regula aspectos de jubilación patronal, mientras que el ordinario regula exclusivamente la jornada de trabajo.','El contrato ordinario se circunscribe a la relación con una empresa en particular, mientras que el contrato ley se extiende a toda una rama industrial del país.','D','case_based','intermediate',true),
  ('LAB2',4,19,'alegato-final','En un juicio por despido intempestivo, la empresa sostiene que el trabajador firmó una renuncia voluntaria. En su alegato de clausura, el abogado del trabajador señala: “La contraparte argumentará que existe un documento firmado de renuncia; sin embargo, con el peritaje caligráfico y la confesión judicial del gerente se demostró que dicha firma fue obtenida bajo presión y amenaza de denuncia penal, destruyendo el consentimiento requerido por ley”. ¿Qué técnica persuasiva de litigación está empleando el abogado en este fragmento?','Formulación de una propuesta de sentencia condicional.','Planteamiento de un lema de clausura en la fase introductoria.','Improvisación de la teoría del caso al finalizar el debate.','Anticipación a los argumentos más fuertes de la contraparte y refutación directa de su hipótesis probatoria.','D','case_based','intermediate',true),
  ('LAB2',1,20,'procedimientos-judiciales-en-materia-laboral','Don Félix es propietario de una panadería registrada bajo su nombre como persona natural (RUC de persona natural). Su hijo, Carlos, actúa como el administrador del local, contrata al personal y realiza los pagos. Tras una disputa, Carlos despide verbalmente a uno de los panaderos. El panadero presenta una demanda exigiendo su liquidación solidaria tanto a Don Félix (dueño) como a Carlos (administrador). Carlos contesta la demanda pidiendo ser excluido porque “él no es el dueño del negocio ni tiene RUC”. ¿Qué debe resolver el juez?','El juez debe archivar la causa por no haberse constituido previamente una sociedad de responsabilidad limitada (S.R.L.).','El juez debe multar al trabajador por demandar a dos personas naturales por el mismo puesto de trabajo.','El juez debe excluir a Carlos porque la responsabilidad económica recae únicamente sobre el titular del RUC que se beneficia directamente de las ganancias.','El juez debe declarar la responsabilidad solidaria de ambos, ya que Carlos ejercía funciones de dirección y administración a nombre de su principal, encajando en el Art. 36 del Código del Trabajo.','D','case_based','intermediate',true),
  ('LAB2',4,21,'contrato-colectivo-de-trabajo','El Contrato Colectivo de la empresa “Textiles del Ecuador” venció hace tres meses y las partes aún no llegan a un acuerdo para la firma de uno nuevo. Paralelamente, la compañía fue vendida a un grupo empresarial extranjero. El nuevo dueño notifica a los trabajadores que, al haber expirado el plazo del contrato colectivo y cambiar el propietario, las cláusulas acordadas previamente han quedado extinguidas. De acuerdo con el texto analizado sobre la vigencia del Contrato Colectivo, ¿qué sucede con los derechos colectivos en este escenario?','Queda suspendido por 180 días hasta que el nuevo dueño decida si lo ratifica o lo anula.','Su vigencia se mantiene e irá más allá del tiempo señalado mientras no se logre un nuevo acuerdo, incluso si la empresa es vendida o cambia de dueño.','El contrato colectivo pierde de inmediato su vigencia por el cambio de propietario.','Pierde validez únicamente respecto al incremento salarial, manteniendo vigentes solo las cláusulas de seguridad industrial.','B','case_based','intermediate',true),
  ('LAB2',4,22,'huelga','El sindicato de trabajadores de un hospital público del sistema de salud decide declarar la huelga debido al incumplimiento grave del contrato colectivo. Notifican la paralización a la autoridad de trabajo fijando como fecha de inicio de la huelga 5 días después de la notificación. De acuerdo con el Art. 514 del Código del Trabajo citado en el texto, ¿cuál es el requisito especial de tiempo aplicable a las instituciones que prestan servicios públicos de salud?','La huelga puede iniciarse de manera inmediata, pues la salud es un derecho constitucional prioritario.','La huelga está absolutamente prohibida en el sector de la salud bajo cualquier circunstancia.','Requiere una notificación previa de 3 días laborables fijada por el Tribunal de Conciliación y Arbitraje.','La declaración de huelga debe hacerse con una anticipación mínima de 20 días a la paralización de las actividades.','D','case_based','intermediate',true),
  ('LAB2',4,23,'huelga','Concluida la huelga solidaria de 3 días laborables en la empresa “Logística del Sur”, un grupo de trabajadores no se reincorpora a sus labores al cuarto día sin justificación alguna. Al ser requeridos, los trabajadores alegan que cuentan con la garantía de un año de estabilidad laboral aplicable a las huelgas en general. Conforme a las reglas específicas de la huelga solidaria descritas en la doctrina, ¿es correcta la pretensión de los trabajadores?','Sí, pero solo si la huelga fue calificada previamente por el Ministerio de Salud Pública.','No, pero el empleador solo puede sancionarlos con una amonestación escrita reteniendo el 10% del sueldo.','Sí, porque toda huelga lícita concede automáticamente un año de estabilidad contra despidos.','No, porque en la huelga solidaria no se reconoce la estabilidad de un año, y el empleador puede solicitar la aprobación del visto bueno por no reiniciar las labores.','D','case_based','intermediate',true),
  ('LAB2',4,24,'contrato-colectivo-de-trabajo','La directiva de un sindicato de la industria textil busca comprender el alcance territorial e institucional de un Contrato Colectivo Ordinario frente a la posibilidad de impulsar un Contrato Ley para toda la actividad textil ecuatoriana. A partir de la distinción dogmática entre ambos tipos de contratación descrita en la normativa y doctrina laboral, ¿cuál es la diferencia fundamental en cuanto a su ámbito de aplicación?','El contrato ley solo regula aspectos de jubilación patronal, mientras que el ordinario regula exclusivamente la jornada de trabajo.','El contrato ordinario rige a nivel nacional para todas las industrias, mientras que el contrato ley rige solo dentro de una fábrica.','El contrato ordinario se circunscribe a la relación con una empresa en particular, mientras que el contrato ley se extiende a toda una rama industrial del país.','El contrato ordinario es de cumplimiento voluntario, mientras que el contrato ley solo aplica a las empresas del sector público.','C','case_based','intermediate',true),
  ('LAB2',4,25,'contrato-colectivo-de-trabajo','El Presidente de la República expidió un Decreto Ejecutivo declarando obligatorio un contrato colectivo para el sector camaronero de la provincia del Guayas, fijando su vigencia en el plazo máximo previsto en la ley. Han transcurrido un año y diez meses desde su emisión, y ninguna de las partes ha manifestado la voluntad de darlo por terminado. ¿Cuál es el plazo máximo de vigencia de dicho contrato y cuál es su situación jurídica al aproximarse al vencimiento?','Su plazo es de 3 años e ingresa automáticamente a proceso de arbitraje obligatorio.','Su plazo máximo es de dos años y se entiende prorrogado por igual tiempo si las 2/3 partes no expresan voluntad contraria tres meses antes de expirar.','Su plazo es indefinido mientras subsistan las empresas que firmaron la solicitud.','Se extingue indefectiblemente a los dos años, quedando prohibida cualquier prórroga por Decreto Ejecutivo.','B','case_based','intermediate',true),
  ('LAB2',3,26,'formas-extraordinarias-de-conclusion-del-proceso','Si un empleador revisa minuciosamente la demanda presentada por un excolaborador y constata que, efectivamente, se le adeudan los rubros calculados y no desea continuar con el desgaste del litigio, ¿cuál es la opción procesal más idónea contemplada en la normativa analizada para terminar el proceso?','Presentar una reconvención conexa alegando daños y perjuicios morales.','El allanamiento o el cumplimiento directo de la obligación materia de la demanda.','Solicitar la declaratoria de rebeldía voluntaria para congelar los intereses.','Formular excepciones previas de falta de legitimidad en la causa.','B','case_based','intermediate',true),
  ('LAB2',4,27,'jubilacion','Un afiliado al IESS tiene 60 años de edad y acredita 360 imposiciones mensuales (30 años de aportes). Según el Art. 185 de la Ley de Seguridad Social, ¿qué derecho le asiste?','Jubilación por edad avanzada.','Jubilación ordinaria de vejez.','Jubilación por invalidez total.','Pensión asistencial no contributiva.','B','normative','intermediate',true),
  ('LAB2',4,28,'contrato-colectivo-de-trabajo','Un trabajador firma un contrato individual de trabajo en el cual pacta un fondo de capacitación inferior al establecido en el Contrato Colectivo de la empresa. Al momento de reclamar la diferencia, la gerencia argumenta que prevalece la autonomía de la voluntad reflejada en el contrato individual que el trabajador firmó voluntariamente. Considerando la jerarquía y fuerza vinculante del Contrato Colectivo de Trabajo, ¿cuál de las siguientes afirmaciones es jurídicamente correcta?','La cláusula del contrato individual es válida únicamente si cuenta con el visto bueno del inspector del trabajo.','Ambas partes deben someter la controversia a un arbitraje privado para determinar qué cláusula se aplica.','El contrato individual prevalece siempre que haya sido firmado libremente por el trabajador.','El Contrato Colectivo tiene mayor peso jurídico que los contratos individuales de trabajo y debe ser respetado por encima de acuerdos particulares.','D','case_based','intermediate',true),
  ('LAB2',4,29,'contrato-colectivo-de-trabajo','En la empresa “Logística del Pacífico S.A.”, un grupo de trabajadores que no pertenece al sindicato mayoritario consulta a la dirección de Recursos Humanos si las mejoras salariales y los beneficios estipulados en el Contrato Colectivo recientemente suscrito les son aplicables. El representante del empleador sostiene que dichos beneficios son exclusivos para los afiliados a la organización sindical. Con base en las características fundamentales del Contrato Colectivo descritas en el texto, ¿es correcta la postura de la empresa?','Sí, pero únicamente si el Ministerio del Trabajo emite una resolución especial de extensión para los no afiliados.','Sí, porque el contrato colectivo genera derechos únicamente para quienes pagan la cuota sindical de la organización.','No, pero su aplicación a los no afiliados está sujeta a que estos reduzcan sus horas de jornada laboral.','No, porque una de sus características esenciales es que aplica para todos y cada uno de los trabajadores de la empresa, aunque no estén afiliados al sindicato.','D','case_based','intermediate',true),
  ('LAB2',2,30,'demanda-laboral','Al redactar la contestación a la demanda, el abogado corporativo debe pronunciarse de manera obligatoria sobre ciertos elementos planteados por el trabajador. De acuerdo con el Art. 151 del COGEP, ¿cuál es la forma correcta en la que debe estructurarse este pronunciamiento?','Basta con una negativa general y abstracta de toda la demanda para que el juez la califique de forma válida.','Debe adjuntar copias notariales de la constitución de la empresa, omitiendo los pronunciamientos sobre documentos ajenos de forma obligatoria.','Únicamente debe fundamentar las excepciones previas, dejando el pronunciamiento de los hechos para la fase de alegatos de la audiencia única.','Debe pronunciarse en forma expresa sobre cada una de las pretensiones, sobre la veracidad de los hechos y sobre la autenticidad de la prueba documental, indicando categóricamente lo que admite y lo que niega.','D','case_based','intermediate',true),
  ('PEN1',3,1,'antijuridicidad-y-causas-de-justificacion','Uno de los requisitos de la legítima defensa es:','Las armas usadas para defenderse.','Agresión actual e ilegítima.','La conducta agresora.','La tipicidad de la conducta.','B','conceptual','intermediate',true),
  ('PEN1',3,2,'culpabilidad','¿Qué es el delito preterintencional?','Cuando el autor manifiesta en forma clara al exterior su voluntad de delinquir.','Cuando la persona realiza una acción u omisión de la cual se produce un resultado más grave de aquel que quiso causar.','Cuando el autor cumple con los presupuestos de ley.','Cuando el autor persigue la realización del delito y muestra su resolución inequívoca tendiente al fin delictivo.','B','conceptual','intermediate',true),
  ('PEN1',3,3,'tipicidad','La tipicidad es:','La conducta delictiva del autor.','La capacidad de tener voluntad y conciencia del autor.','La adecuación de un hecho cometido a la descripción que de ese hecho hace la ley penal.',null,'C','conceptual','intermediate',false),
  ('PEN1',3,4,'tipicidad','¿Qué son los bienes jurídicos protegidos?','Todo derecho constitucional de los ciudadanos que, por su importancia, merece ser protegido por el Derecho Penal.','Los bienes inmateriales que tienen las personas.','Los bienes muebles e inmuebles de la víctima.',null,'A','conceptual','intermediate',false),
  ('PEN1',3,5,'culpabilidad','El error que recae sobre la ilicitud de la conducta, y no sobre los elementos descriptivos del tipo, se denomina:','Caso fortuito.','Dolo eventual.','Error de tipo.','Error de prohibición.','D','conceptual','intermediate',true),
  ('PEN1',4,6,'escuelas-juridico-penales-y-finalidad-de-la-pena','Las teorías que combinan elementos retributivos y preventivos en la finalidad de la pena se denominan:','Teorías relativas.','Teorías absolutas.','Teorías positivistas.','Teorías de la unión o mixtas.','D','conceptual','intermediate',true),
  ('PEN1',3,7,'tipicidad','El elemento del tipo penal que expresa la conducta, generalmente en infinitivo (matar, sustraer, engañar), se denomina:','Elemento subjetivo.','Sujeto pasivo.','Bien jurídico protegido.','Verbo rector.','D','conceptual','intermediate',true),
  ('PEN1',2,8,'iter-criminis','Según el tratadista Felipe Rodríguez Moreno, ¿cuáles son los niveles de la fase externa del iter criminis?','La acción, la tipicidad y la antijuridicidad.','La ideación, la deliberación y la resolución.','Las resoluciones manifestadas, actos preparatorios y actos ejecutivos.',null,'C','conceptual','intermediate',false),
  ('PEN1',3,9,'tipicidad','¿Qué es el sujeto activo calificado?','Es cuando el sujeto activo tiene una especial calificación de conducta.','Es la persona contra la cual se comete la infracción.','Es cuando el sujeto activo califica a sus víctimas por nivel de vulnerabilidad.','Es cuando el sujeto activo está revestido de una especial cualidad que lo identifica y distingue de los demás.','D','conceptual','intermediate',true),
  ('PEN1',2,10,'accion-y-omision','La acción desde el punto de vista de la teoría causalista se entendía como:','Un impulso de la voluntad que genera un movimiento corporal que supone la causación de una modificación en el mundo externo, es decir, de un resultado.','El pensamiento que origina una acción que modifica el mundo exterior.','Una idea inicial que se exterioriza con una acción delictiva tipificada en la ley.','La actividad humana.','A','conceptual','intermediate',true),
  ('PEN1',1,11,'alcances-del-principio-de-legalidad','El requisito de LEX STRICTA es conocido también como:','Principio de oralidad.','Principio de favorabilidad.','Prohibición de analogía.','Prohibición de temporalidad.','C','conceptual','intermediate',true),
  ('PEN1',4,12,'teorias-preventivas-de-la-pena','La prevención especial, como finalidad de la pena, busca principalmente:','Intimidar a toda la sociedad.','Reparar el daño patrimonial de la víctima.','Evitar que el propio condenado reincida.','Sancionar a las personas jurídicas.','C','conceptual','intermediate',true),
  ('PEN1',2,13,'iter-criminis','¿Cuándo se verifica la fase de ejecución?','Cuando se planifica el delito en la mente del autor.','Cuando se realizan todos los actos preparatorios para la consumación de la infracción.','Cuando la conducta efectivamente pone en peligro o lesiona el bien jurídico protegido ajeno.',null,'C','conceptual','intermediate',false),
  ('PEN1',3,14,'culpabilidad','¿Cuándo existe dolo directo?','La acción y la antijuridicidad.','El elemento cognitivo (conocimiento) y el volitivo (voluntad).','La voluntad y la conciencia.','El dolo y la culpa.','B','conceptual','intermediate',true),
  ('PEN1',3,15,'antijuridicidad-y-causas-de-justificacion','¿Cuántos requisitos exige el Art. 33 del COIP para que exista legítima defensa?','Cinco.','Tres.','Cuatro.','Dos.','B','normative','intermediate',true),
  ('PEN1',3,16,'antijuridicidad-y-causas-de-justificacion','¿Qué significa la necesidad racional de defensa, como requisito para la legítima defensa?','Que el medio deberá ser el necesario y el que se encuentre al alcance de quien se defiende, sin importar que sea desproporcionado.','Que debe existir una defensa legítima ante la agresión.','Que no debe existir agresión alguna.','Que la agresión viola el derecho a la defensa.','A','conceptual','intermediate',true),
  ('PEN1',4,17,'teorias-preventivas-de-la-pena','Las teorías relativas de la pena también se conocen como teorías de:','Retribución.','Prevención.','Individualización.','Reincidencia.','B','conceptual','intermediate',true),
  ('PEN1',2,18,'iter-criminis','Los actos materiales dirigidos a facilitar la ejecución del delito, generalmente no punibles, se denominan:','Resoluciones manifestadas.','Consumación.','Actos ejecutivos.','Actos preparatorios.','D','conceptual','intermediate',true),
  ('PEN1',2,19,'accion-y-omision','Según el Art. 24 del Código Orgánico Integral Penal, es causa de exclusión de la conducta:','La fuerza física condicionada.','La fuerza física irresistible.','La fuerza física resistible.',null,'B','normative','intermediate',false),
  ('PEN1',2,20,'accion-y-omision','¿Cuándo una persona actúa con culpa?','Cuando cumple con su deber objetivo de cuidado.','Cuando observa el deber objetivo de cuidado.','Cuando no conoce su deber objetivo de cuidado.','Cuando infringe el deber objetivo de cuidado que personalmente le corresponde, produciendo un resultado dañoso.','D','conceptual','intermediate',true),
  ('PEN1',3,21,'antijuridicidad-y-causas-de-justificacion','La legítima defensa, según el tratadista Felipe Rodríguez Moreno, es:','Los actos necesarios para lograr la aprehensión del agresor.','La defensa necesaria para sancionar al delincuente.','Los actos necesarios para castigar al agresor.','La defensa necesaria para rechazar un ataque antijurídico.','D','conceptual','intermediate',true),
  ('PEN1',3,22,'culpabilidad','Las formas de participación en la infracción penal son:','Como autores o cómplices.','Como sujeto activo y como sujeto pasivo.','Con dolo y con culpa.',null,'A','conceptual','intermediate',false),
  ('PEN1',3,23,'tipicidad','¿Cuándo el error de tipo es invencible?','Es aquel que hubiese podido evitarse si se hubiera observado el debido cuidado, por lo que puede considerarse un error imprudente.','Es el que no logra vencerse por la fuerza de voluntad.','Es el que logra vencerse por la fuerza de voluntad.','Es el que no hubiese logrado evitarse ni aun aplicando la debida diligencia.','D','conceptual','intermediate',true),
  ('PEN1',1,24,'alcances-del-principio-de-legalidad','¿En qué artículo de la Constitución del Ecuador se consagra el principio de legalidad penal?','Art. 66.','Art. 82.','Art. 76 numeral 3.','Art. 11.','C','normative','intermediate',true),
  ('PEN1',3,25,'culpabilidad','El dolo en el que el autor sabe con seguridad que producirá un resultado adicional, aunque no lo persiga, se denomina:','Dolo eventual.','Dolo directo.','Culpa.','Dolo de segundo grado.','D','conceptual','intermediate',true),
  ('PEN1',2,26,'iter-criminis','El aforismo “Cogitationis poenam nemo patitur”, atribuido a Ulpiano, significa que:','Nadie sufre pena por su pensamiento.','La ley penal es siempre retroactiva.','La tentativa se sanciona igual que la consumación.','Todo delito debe consumarse para ser punible.','A','conceptual','intermediate',true),
  ('PEN1',2,27,'accion-y-omision','La culpa o la imprudencia tiene su sustento en:','La infracción de tránsito.','La infracción del tipo penal.','La infracción al deber objetivo de cuidado.','La infracción penal.','C','conceptual','intermediate',true),
  ('PEN1',3,28,'culpabilidad','La culpabilidad implica:','Que para que una persona sea considerada responsable penalmente debe actuar con voluntad y conciencia.','Que para que una persona sea considerada responsable penalmente deberá ser imputable y actuar con conocimiento de la antijuridicidad de su conducta.','Que para que una persona sea considerada responsable penalmente deberá ser mayor de edad.',null,'B','conceptual','intermediate',false),
  ('PEN1',2,29,'accion-y-omision','La omisión se clasifica en:','Omisión propia e impropia.','Omisión simple y compuesta.','Omisión finalista y causalista.',null,'A','conceptual','intermediate',false),
  ('PEN1',2,30,'iter-criminis','El Iter Criminis tiene dos fases:','Fase inicial y posterior.','Fase interna y fase externa.','Fase de ideación y de acción.',null,'B','conceptual','intermediate',false),
  ('CIV3',4,1,'donaciones-entre-vivos','La transferencia debe ser a título gratuito. Es decir, hay un desprendimiento de bienes, sin compensación por la otra parte. Pero esta no es una regla absoluta, esto es:','Características de donación entre vivos.','Elementos constitutivos de la accesión.','Elementos constitutivos de la donación entre vivos.','Características de la accesión.','A','conceptual','intermediate',true),
  ('CIV3',4,2,'donaciones-entre-vivos','La donación entre vivos puede revocarse por:','Es irrevocable en todos los casos.','Disposición de un notario.','Ingratitud.','El donante se sienta vulnerable ante el donatario.','C','conceptual','intermediate',true),
  ('CIV3',1,3,'sucesion-por-causa-de-muerte','Por la sucesión por causa de muerte, el que fallece:','Acarrea.','Transmite.','Transfiere.','Emite.','B','conceptual','intermediate',true),
  ('CIV3',4,4,'donaciones-entre-vivos','No hay donación:','En el terreno que dio María a una Escuela.','En el comodato de una cosa cualquiera.','En los sacos de arroz que dieron a los afectados del terremoto.','En el barco que dio Pedro a los refugiados.','B','conceptual','intermediate',true),
  ('CIV3',2,5,'asignaciones-testamentarias','La condición impuesta al heredero de no contraer matrimonio:','Se tendrá que decir con quién.','Se tendrá por no escrita.','Se tendrá por válida.','Se tendrá que cumplirse.','B','conceptual','intermediate',true),
  ('CIV3',4,6,'donaciones-entre-vivos','Indique cuáles son las causas de indignidad para recibir una donación:','Atentar contra las personas más cercanas al donante, tales como: cónyuge, ascendientes o descendientes.','Todas son correctas.','No haber socorrido al donante o causante cuando éste se encontraba en estado de desvalimiento.','Perpetrado el delito de homicidio en la persona del donante.','B','conceptual','intermediate',true),
  ('CIV3',4,7,'donaciones-entre-vivos','¿Quiénes pueden recibir donación?','Pueden recibir las donaciones todas las personas que no están comprendidas exclusivamente en las incapacidades expresamente señaladas por la ley.','Pueden recibir las donaciones todas las personas que no están comprendidas exclusivamente en las indignidades expresamente señaladas por la ley.','Pueden recibir las donaciones todas las personas que no están comprendidas en las incapacidades o indignidades expresamente señaladas por la ley.','Pueden recibir las donaciones todas las personas que están comprendidas en las incapacidades o indignidades expresamente señaladas por la ley.','C','conceptual','intermediate',true),
  ('CIV3',2,8,'asignaciones-testamentarias','Por la destrucción de la especie legada:','Se ejecuta y debe cumplirse con otro.','Es válida la obligación.','Debe cumplirse la obligación de pagar el legado.','Se extingue la obligación de pagar el legado.','D','conceptual','intermediate',true),
  ('CIV3',1,9,'sucesion-por-causa-de-muerte','La Constitución del Ecuador determina que para proteger los derechos de la persona:','Se garantiza el derecho solo del testamento.','Se garantiza el derecho de testar y de no heredar.','Se garantiza el derecho de heredar y no testar.','Se garantiza el derecho de testar y de heredar.','D','normative','intermediate',true),
  ('CIV3',4,10,'donaciones-entre-vivos','¿Por qué la donación entre vivos es a título gratuito?','Ninguna de las anteriores.','Porque una de las partes entrega sus bienes sin ninguna contraprestación.','Podrá ser gratuita si la persona que dona así lo establece.','Porque es su característica principal.','B','conceptual','intermediate',true),
  ('CIV3',1,11,'sucesion-por-causa-de-muerte','Si el difunto hubiera dejado más de un hijo:','La herencia se divide entre los hijos, por partes iguales.','La herencia se divide entre los hijos, por partes desiguales.','La herencia es proindivisa siempre.','La herencia no se divide entre los hijos.','A','conceptual','intermediate',true),
  ('CIV3',2,12,'asignaciones-testamentarias','Si el asignatario muere antes de cumplirse la condición:','Transfiere los derechos.','No transmite derecho alguno.','Transfiere derecho parcialmente.','Transmite los derechos.','B','conceptual','intermediate',true),
  ('CIV3',3,13,'apertura-de-la-sucesion-aceptacion-repudiacion-e-inventario','La aceptación de la herencia:','Solo expresa.','Tangible.','Puede ser tácita o expresa.','Solo tácita.','C','conceptual','intermediate',true),
  ('CIV3',2,14,'asignaciones-testamentarias','No vale el legado de:','Bienes de propiedad de la persona que fallece.','Bienes de propiedad nacional o municipal.','Bienes de propiedad del causante.','Bienes de propiedad del testador.','B','conceptual','intermediate',true),
  ('CIV3',2,15,'asignaciones-testamentarias','La porción conyugal, las legítimas y la cuarta de mejoras son:','Asignaciones forzosas.','Características de la sucesión por causa de muerte.','Ninguna de las anteriores.','Facultades del testador.','A','conceptual','intermediate',true),
  ('CIV3',1,16,'presuncion-de-muerte-por-desaparicion','Respecto a la presunción de muerte por desaparición, ¿cuál será el día presuntivo de muerte que fijará el juez?','El último del primer año, contado desde la fecha de las últimas noticias, y transcurridos tres años desde la misma fecha.','Ninguna de las anteriores.','El último día que alguien lo vio con vida, y transcurrido un año desde la misma fecha.','El último día que se tuvo noticia de la persona, y transcurridos cinco años desde la misma fecha.','A','conceptual','intermediate',true),
  ('CIV3',1,17,'sucesion-por-causa-de-muerte','José asignó un solar a Juan, pero este en vida lo vendió; con la sucesión por causa de muerte:','José alega que no está revocado el legado.','José debe demandar el pago en efectivo.','José perdió el legado.','José debe exigir el legado.','C','conceptual','intermediate',true),
  ('CIV3',4,18,'donaciones-entre-vivos','La donación hecha a los hijos por escritura pública, ¿es revocable o irrevocable, y por qué?','Es revocable, porque no se reservó la facultad de revocarla y esta no aparece que sea por causa de muerte.','Es irrevocable, porque se reservó la facultad de no revocarla y esta aparece que sea por causa de muerte.','Es irrevocable, porque se reservó la facultad de revocarla y esta no aparece que sea por causa de muerte.','Es irrevocable, porque no se reservó la facultad de revocarla y esta no aparece que sea por causa de muerte.','D','conceptual','intermediate',true),
  ('CIV3',1,19,'sucesion-intestada','Son llamados a la sucesión intestada:','Los compañeros de trabajo.','Los ahijados.','Los vecinos del difunto.','Los hijos del difunto.','D','conceptual','intermediate',true),
  ('CIV3',2,20,'el-testamento','No son hábiles para testar:','El menor de dieciocho años.','El que se halla en el extranjero.','El mayor de 20 años.','El mayor de 30 años.','A','conceptual','intermediate',true),
  ('CIV3',1,21,'el-testamento','La sucesión testamentaria, de acuerdo a su naturaleza, puede ser:','Onerosa.','Universal o singular.','Gratuita.','Indeterminada.','B','conceptual','intermediate',true),
  ('CIV3',4,22,'donaciones-entre-vivos','Hay donación:','En los sacos de arroz que dieron a los afectados del terremoto.','En dejar interrumpir la prescripción.','Los servicios personales gratuitos.','En el comodato.','A','conceptual','intermediate',true),
  ('CIV3',3,23,'ejecutores-testamentarios-o-albaceas','Doctrinariamente, el albacea se asimila a un:','Medida.','Mandato.','Precepto.','Modelo.','B','conceptual','intermediate',true),
  ('CIV3',4,24,'donaciones-entre-vivos','No hay donación:','En los sacos de arroz que dieron a los afectados del terremoto.','En el terreno que dio María a una Escuela.','En el barco que dio Pedro a los refugiados.','En dejar de interrumpir la prescripción.','D','conceptual','intermediate',true),
  ('CIV3',4,25,'donaciones-entre-vivos','Donación por el deseo del causante, que se traduce en el testamento:','Donación entre cónyuges.','Donación mortis causa.','Donación entre vivos.','Donación entre primos.','B','conceptual','intermediate',true),
  ('CIV3',2,26,'asignaciones-testamentarias','La condición impuesta al heredero de permanecer en estado de viudez para siempre:','Se tendrá que cumplirse.','Se tendrá por válida.','Se tendrá que decir con quién.','Se tendrá por no escrita.','D','conceptual','intermediate',true),
  ('CIV3',1,27,'sucesion-por-causa-de-muerte','Se produce por el deseo del de cuius, que se traduce en su testamento. ¿A qué figura jurídica nos referimos?','Donación entre cónyuges.','Ninguna de las anteriores.','Donación mortis causa.','Donación inter vivos.','C','conceptual','intermediate',true),
  ('CIV3',4,28,'donaciones-entre-vivos','Dentro de la donación entre vivos, figuran dos elementos esenciales, estos son:','Elemento de voluntariedad y elementos que penden de una condición.','Elemento constitutivo y elemento resolutivo.','Elemento subjetivo y elemento objetivo.','Elementos coercitivos y elementos constitutivos.','C','conceptual','intermediate',true),
  ('CIV3',3,29,'apertura-de-la-sucesion-aceptacion-repudiacion-e-inventario','Consiste en no hacer a los herederos que aceptan la herencia responsables sino hasta el valor de los bienes que han heredado:','Beneficio de ventas.','Beneficio de respaldo.','Beneficio de inventario.','Beneficio de embargo.','C','conceptual','intermediate',true),
  ('CIV3',1,30,'presuncion-de-muerte-por-desaparicion','Se consideran efectos de la posesión provisional de los bienes del desaparecido:','Quedará disuelta la sociedad conyugal, si la hubiere con el desaparecido.','Se dará la posesión provisional a los herederos presuntivos.','Se procederá a la apertura y publicación del testamento, si el desaparecido hubiere dejado alguno.','Todas las anteriores.','D','conceptual','intermediate',true);
insert into public.questions (unit_id,topic_id,legal_article_id,question_text,question_type,difficulty,source_reference,is_active,is_verified) select u.id,t.id,null,b.question_text,b.question_type,b.difficulty,'DATASET:S345:BANK150:'||b.code||':'||lpad(b.qnum::text,2,'0'),true,b.is_verified from tmp_s345_bank b join public.subjects s on s.code=b.code join public.units u on u.subject_id=s.id and u.unit_number=b.unit_number left join public.topics t on t.unit_id=u.id and t.slug=b.topic_slug;
insert into public.question_options (question_id,option_key,option_text,sort_order) select qn.id,'A',b.option_a,1 from tmp_s345_bank b join public.questions qn on qn.source_reference='DATASET:S345:BANK150:'||b.code||':'||lpad(b.qnum::text,2,'0') where b.option_a is not null;
insert into public.question_options (question_id,option_key,option_text,sort_order) select qn.id,'B',b.option_b,2 from tmp_s345_bank b join public.questions qn on qn.source_reference='DATASET:S345:BANK150:'||b.code||':'||lpad(b.qnum::text,2,'0') where b.option_b is not null;
insert into public.question_options (question_id,option_key,option_text,sort_order) select qn.id,'C',b.option_c,3 from tmp_s345_bank b join public.questions qn on qn.source_reference='DATASET:S345:BANK150:'||b.code||':'||lpad(b.qnum::text,2,'0') where b.option_c is not null;
insert into public.question_options (question_id,option_key,option_text,sort_order) select qn.id,'D',b.option_d,4 from tmp_s345_bank b join public.questions qn on qn.source_reference='DATASET:S345:BANK150:'||b.code||':'||lpad(b.qnum::text,2,'0') where b.option_d is not null;
insert into public.question_answers (question_id,correct_option_id,correct_explanation) select qn.id,qo.id,'Respuesta marcada como correcta en el Banco_150_Preguntas_Derecho_Resueltas aportado por el usuario: '||qo.option_key||'. '||qo.option_text from tmp_s345_bank b join public.questions qn on qn.source_reference='DATASET:S345:BANK150:'||b.code||':'||lpad(b.qnum::text,2,'0') join public.question_options qo on qo.question_id=qn.id and qo.option_key=b.correct_key;
insert into public.question_option_feedback (option_id,explanation) select qo.id,case when qo.option_key=b.correct_key then 'Esta opción coincide con la respuesta marcada como correcta en el banco resuelto utilizado como fuente.' else 'Esta opción no coincide con la respuesta marcada como correcta en el banco resuelto utilizado como fuente. Revise el compendio de la unidad antes de volver a intentarlo.' end from tmp_s345_bank b join public.questions qn on qn.source_reference='DATASET:S345:BANK150:'||b.code||':'||lpad(b.qnum::text,2,'0') join public.question_options qo on qo.question_id=qn.id;
insert into public.academic_dataset_versions (dataset_key,version_label,description,source_basis,checksum,applied_at,applied_by) values ('semestres-3-4-5-material-disponible','1.0-source-grounded','Carga estructurada de los semestres tercero, cuarto y quinto con el material disponible. Tercero y Quinto conservan unidades faltantes o ambiguas como tales; no se rellenan silenciosamente. Incluye el banco exacto de 150 preguntas resueltas de cuarto semestre.','Compendios tercero.zip; cinco compendios unificados de cuarto semestre; Banco_150_Preguntas_Derecho_Resueltas(1).docx; Compendios Quinto.zip.','b87c842ef99a676ce4f1164df892a69b588d1b8075ca71c285b22757040c5c39',now(),null) on conflict (dataset_key) do update set version_label=excluded.version_label, description=excluded.description, source_basis=excluded.source_basis, checksum=excluded.checksum, applied_at=now();
